/bin/bash -lc "date -u && python - <<'PY'
from sim import Sim
import numpy as np
sim=Sim()
q1=np.array([ 0.876,  1.194, -2.033, -2.764,  2.683,  0.868,  0.681])
q2=np.array([ 1.193,  0.069, -1.198, -2.052, -1.559,  2.935, -2.006])
q3=np.array([ 1.109,  0.791, -1.684, -2.056, -0.787,  2.107, -0.928])

def rollout(mode):
    sim.reset(); sim.data.ctrl[7]=210
    def move(q,s):
        c0=sim.data.ctrl[:7].copy()
        for i in range(s):
            a=(i+1)/s; sim.data.ctrl[:7]=c0*(1-a)+q*a; sim.step(1)
    def hold(q,s):
        sim.data.ctrl[:7]=q
        for _ in range(s): sim.step(1)
    move(q1,260); hold(q1,110); move(q2,280); hold(q2,120)
    if mode==0:
        hold(q2,400)
        hold(q2,500)
    elif mode==1:
        move(q3,140); hold(q3,240); hold(q3,500)
    elif mode==2:
        move((q2*0.7+q3*0.3),120); hold((q2*0.7+q3*0.3),260); hold((q2*0.7+q3*0.3),500)
    elif mode==3:
        move((q2*0.85+q3*0.15),120); hold((q2*0.85+q3*0.15),260); hold((q2*0.85+q3*0.15),500)
    peg=sim.peg_position(); x,y,z=peg
    align=abs(sim.data.xmat[sim.peg_body_id].reshape(3,3)[:,0][0])
    passed=(x>=0.515 and abs(y+0.10)<=0.025 and abs(z-0.52)<=0.020 and align>=0.45)
    return passed,peg,align,len(sim._ctrl_trace)

for m in range(4):
    p,peg,a,n=rollout(m)
    print('mode',m,'pass',p,'peg',peg,'align',a,'steps',n)
    if m==0:
        sim.save_final_state('/work/final_state.npz')
PY"

